bool isPalindrome(const std::string &input) {
    size_t left = 0;
    size_t right = input.size();
    if (right == 0) return true;
    --right; // point to last character

    while (left < right) {
        // Skip spaces on the left
        while (left < right && input[left] == ' ') ++left;
        // Skip spaces on the right
        while (left < right && input[right] == ' ') --right;

        if (left >= right) break;

        char cl = std::tolower(static_cast<unsigned char>(input[left]));
        char cr = std::tolower(static_cast<unsigned char>(input[right]));

        if (cl != cr) return false;

        ++left;
        --right;
    }
    return true;
}

