def min_coins(amount, coins):
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1

    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for c in coins:
            if c <= i and dp[i - c] != float('inf'):
                dp[i] = min(dp[i], dp[i - c] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

