def babylonian_squareroot(n, *, tolerance=1e-12, max_iter=1000):
    """Compute the square root of n using the Babylonian (Newton) method."""
    if n < 0:
        raise ValueError("cannot compute square root of a negative number")
    if n == 0:
        return 0.0
    # Initial guess: use n itself for large numbers, 1 for small numbers
    x = n if n >= 1.0 else 1.0
    for _ in range(max_iter):
        next_x = 0.5 * (x + n / x)
        if abs(next_x - x) < tolerance:
            return next_x
        x = next_x
    return x  # fallback if max_iter reached
