def longest_palindrome(s):
    n = len(s)
    if n < 2:
        return s
    start = 0
    max_len = 1

    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(n):
        # odd length
        l1, r1 = expand(i, i)
        cur_len = r1 - l1 + 1
        if cur_len > max_len:
            start, max_len = l1, cur_len
        # even length
        l2, r2 = expand(i, i + 1)
        cur_len = r2 - l2 + 1
        if cur_len > max_len:
            start, max_len = l2, cur_len

    return s[start:start + max_len]

