def min_cost_climb_stairs(cost):
    n = len(cost)
    if n == 0:
        return 0
    if n == 1:
        return 0  # can start at step 1 (the top) with no cost
    # dp[i] is min cost to reach step i
    dp0 = cost[0]
    dp1 = cost[1]
    for i in range(2, n):
        dpi = cost[i] + min(dp0, dp1)
        dp0, dp1 = dp1, dpi
    return min(dp0, dp1)

