int maxProfit(const std::vector<int>& prices) {
    int n = static_cast<int>(prices.size());
    if (n == 0) return 0;

    std::vector<int> left(n, 0), right(n, 0);

    int min_price = prices[0];
    for (int i = 1; i < n; ++i) {
        min_price = std::min(min_price, prices[i]);
        left[i] = std::max(left[i - 1], prices[i] - min_price);
    }

    int max_price = prices[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        max_price = std::max(max_price, prices[i]);
        right[i] = std::max(right[i + 1], max_price - prices[i]);
    }

    int result = 0;
    for (int i = 0; i < n; ++i) {
        result = std::max(result, left[i] + right[i]);
    }

    return result;
}
